func:
msg.phase = "scan";
msg.url = new URL("/api/automation/followups", env.get("APP_URL")).href;
msg.headers = { Authorization: "Bearer " + env.get("AUTOMATION_TOKEN"), "Content-Type": "application/json" };
msg.payload = { operation: "scan" };
msg.requestTimeout = 15000;
msg.followRedirects = false;
return msg;

if (msg.statusCode !== 200 || !msg.payload || msg.payload.ok !== true) return [null, msg];
const reply = msg.payload;
if (msg.phase === "finish") {
    delete msg.headers;
    if (msg.finishingFailure) {
        node.status({ fill: "yellow", shape: "ring", text: "Check failed; status recorded" });
        node.warn("Follow-up check failed; failure recorded in PondoPath.");
    } else {
        const counts = msg.counts || { created: 0, existing: 0, skipped: 0 };
        node.status({ fill: "green", shape: "dot", text: counts.created + " new tasks" });
        node.log("Follow-up check complete: created=" + counts.created + " existing=" + counts.existing + " skipped=" + counts.skipped);
    }
    return null;
}
if (msg.phase === "scan") {
    msg.runId = reply.runId;
    if (!msg.runId || !Array.isArray(reply.candidates) || reply.candidates.length > 1000) return [null, msg];
    const ids = reply.candidates.filter(item => item.remainingCents > 0 && item.date < reply.referenceDate).map(item => item.expectationId);
    msg.phase = ids.length ? "create" : "finish";
    msg.payload = ids.length ? { operation: "create", runId: msg.runId, expectationIds: ids } : { operation: "finish", runId: msg.runId, success: true };
} else {
    msg.counts = { created: reply.created, existing: reply.existing, skipped: reply.skipped };
    msg.phase = "finish";
    msg.payload = { operation: "finish", runId: msg.runId, success: true };
}
msg.headers = { Authorization: "Bearer " + env.get("AUTOMATION_TOKEN"), "Content-Type": "application/json" };
return [msg, null];

if (!msg.runId || msg.phase === "finish") {
    delete msg.headers;
    node.status({ fill: "red", shape: "ring", text: "Check unavailable; stale notice remains" });
    node.warn("Follow-up check unavailable. Use Check now in PondoPath; no payments or messages were sent.");
    return null;
}
msg.phase = "finish";
msg.finishingFailure = true;
msg.headers = { Authorization: "Bearer " + env.get("AUTOMATION_TOKEN"), "Content-Type": "application/json" };
msg.payload = { operation: "finish", runId: msg.runId, success: false, errorCode: msg.error ? "CONNECTION_ERROR" : "HTTP_ERROR" };
delete msg.error;
return msg;
